import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"FactCheck & FactCheckClaim Models","description":"","frontmatter":{},"headers":[],"relativePath":"backend/models/fact-check.md","filePath":"backend/models/fact-check.md"}`),a={name:`backend/models/fact-check.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="factcheck-factcheckclaim-models" tabindex="-1">FactCheck &amp; FactCheckClaim Models <a class="header-anchor" href="#factcheck-factcheckclaim-models" aria-label="Permalink to &quot;FactCheck &amp; FactCheckClaim Models&quot;">​</a></h1><p>TechyNews uses an automated verification pipeline to ensure AI hallucinations don&#39;t reach production. This is powered by two distinct models.</p><h2 id="factcheck-php" tabindex="-1"><code>FactCheck.php</code> <a class="header-anchor" href="#factcheck-php" aria-label="Permalink to &quot;`FactCheck.php`&quot;">​</a></h2><p>Represents a single &quot;run&quot; or verification session for a specific <code>Article</code>.</p><p><strong>Columns:</strong></p><ul><li><code>article_id</code> (Foreign Key)</li><li><code>overall_verdict</code> (Enum): <code>true</code>, <code>false</code>, <code>mixed</code>, <code>unverifiable</code>.</li><li><code>confidence_score</code> (Integer 0-100)</li><li><code>raw_ai_response</code> (JSON): The raw analysis from Gemini before parsing.</li></ul><p><strong>Relationships:</strong></p><ul><li><code>belongsTo(Article::class)</code></li><li><code>hasMany(FactCheckClaim::class)</code></li></ul><h2 id="factcheckclaim-php" tabindex="-1"><code>FactCheckClaim.php</code> <a class="header-anchor" href="#factcheckclaim-php" aria-label="Permalink to &quot;`FactCheckClaim.php`&quot;">​</a></h2><p>Represents an individual statement extracted from the article that was verified against trusted sources.</p><p><strong>Columns:</strong></p><ul><li><code>fact_check_id</code> (Foreign Key)</li><li><code>claim_text</code> (String): &quot;Apple announced the M4 chip on Tuesday.&quot;</li><li><code>verdict</code> (Enum): <code>true</code>, <code>false</code>, <code>misleading</code>.</li><li><code>evidence</code> (Text): The quoted evidence from a trusted source (via Jina Reader/Google).</li><li><code>source_url</code> (String): The URL of the verifying evidence.</li></ul><h2 id="business-logic-integration" tabindex="-1">Business Logic Integration <a class="header-anchor" href="#business-logic-integration" aria-label="Permalink to &quot;Business Logic Integration&quot;">​</a></h2><p>These models are primarily manipulated by the <code>FactCheckService</code>. When an article is generated, the agent automatically spawns a <code>FactCheck</code> run, which populates multiple <code>FactCheckClaim</code> rows.</p>',14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};